"""Rebuild the static Atlas from its reviewed public content. Python standard library only."""
from pathlib import Path
import json,html,shutil,re,hashlib
R=Path(__file__).resolve().parent;D=R/'dist';D.mkdir(exist_ok=True)
A=json.loads((R/'content/atlas.json').read_text(encoding='utf-8'));P=A['papers'];byid={p['ssrn_id']:p for p in P}
e=html.escape
BASE='https://boundedness-atlas.madmanmuzza.chatgpt.site'
REPO='https://github.com/thantiklermcirony/boundedness-atlas'
nav=[('/','The expedition'),('/discoveries/','Discoveries'),('/predictions/','Predictions'),('/biology/','Biology'),('/papers/','The papers')]
ICON="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 64 64'%3E%3Crect width='64' height='64' rx='32' fill='%2311281f'/%3E%3Cellipse cx='32' cy='32' rx='12' ry='24' fill='none' stroke='%23d8f57d' stroke-width='3'/%3E%3Cpath d='M10 32h44' stroke='%23d8f57d' stroke-width='3'/%3E%3C/svg%3E"
def linkpaper(i,label=None):
 p=byid[str(i)];return f'<a href="/papers/{p["key"]}/">{e(label or p["title"])}</a>'
def sources(ids):return '<div class="source-links">'+''.join(linkpaper(i,'Read '+str(i)) for i in ids)+'</div>'
def button(url,label,ghost=False):return f'<a class="button {"ghost" if ghost else ""}" href="{url}">{label} <span aria-hidden="true">↗</span></a>'
def hero(title,desc,art='specimens',eyebrow='The Boundedness Atlas',home=False):
 return f'<section class="hero {"" if home else "chapter-hero"}"><img src="/assets/{art}.jpg" alt="{dict(entrance="Imagined conservatory with floating botanical islands",specimens="Imagined cabinet of luminous specimens and brass instruments",biology="Imagined biology greenhouse with luminous cellular specimens")[art]}" fetchpriority="high"><div class="hero-copy"><p class="eyebrow">{eyebrow}</p><h1>{title}</h1><p class="lead">{desc}</p>{"<div class=actions>"+button("/discoveries/","Explore the discoveries")+button("/biology/","Enter biology",True)+"</div>" if home else ""}</div>{"<div class=hero-index><span>Daniel John Murray · Independent research</span><span>41 manuscripts · One connected expedition</span></div>" if home else ""}</section>'
def write(path,title,body,desc='Explore Daniel John Murray’s research on boundedness, state, biological recovery and testable prediction.'):
 dest=D/path.strip('/')/'index.html' if path!='/' else D/'index.html';dest.parent.mkdir(parents=True,exist_ok=True)
 n=''.join(f'<a href="{u}" '+('aria-current="page" ' if path==u else '')+f'>{t}</a>' for u,t in nav)
 content=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{e(desc)}"><title>{e(title)} · The Boundedness Atlas</title><link rel="canonical" href="{BASE}{path}"><meta property="og:title" content="{e(title)} · The Boundedness Atlas"><meta property="og:description" content="{e(desc)}"><link rel="icon" href="{ICON}"><link rel="stylesheet" href="/style.css"><script src="/app.js" defer></script></head><body><a class="skip" href="#main">Skip to content</a><header class="topbar"><a class="brand" href="/"><span class="seal" aria-hidden="true">◈</span><span><b>BOUNDEDNESS ATLAS</b><small>THE MURRAY RESEARCH PROGRAMME</small></span></a><nav class="nav" aria-label="Main navigation">{n}</nav></header><main id="main">{body}</main><footer class="footer"><div><p>Daniel John Murray · Independent research</p><p class="art-credit">An imagined botanical world, illustrated with AI. Artwork is not scientific evidence.</p></div><div><a href="/about/">Evidence &amp; coverage</a><a href="{REPO}">Source repository ↗</a><a href="https://github.com/thantiklermcirony/empirical-observatory">Observatory archive ↗</a></div></footer></body></html>'''
 dest.write_text(content,encoding='utf-8')
def section(body,cls=''):return f'<section class="paper {cls}"><div class="page-wrap">{body}</div></section>'
def route(url,title,text,art):return f'<a class="route-card" href="{url}"><img src="/assets/{art}.jpg" loading="lazy" alt=""><div><span class="eyebrow">Explore ↗</span><h3>{title}</h3><p>{text}</p></div></a>'
home=hero('Life at<br>the edge of<br><em>possible.</em>','What do limits reveal about living systems? An expedition through boundedness, memory, recovery—and the hidden distinctions that change a future.','entrance','A field guide to the edges of possibility',True)
home+='<div class="rail"><span><strong>41</strong> manuscript records</span><span><strong>8</strong> connected contributions</span><span><strong>1</strong> focused biology expedition</span><a href="/about/">What these counts mean ↗</a></div>'
home+=section('''<div class="intro"><p class="section-tag">01 / The question underneath</p><div><h2>A limit is a beginning.<br>What follows from it?</h2><p class="lead">A cell can look recovered and still be depleted. Two communities can share an abundance pattern and behave differently. The same total exposure can lead to different futures.</p><p>The programme began by mapping boundedness: finite capacities, constrained responses and the structure of composition. Across the papers, that investigation developed into a practical question: <strong>what has our description left out that the future can still reveal?</strong></p><p>The combined contribution is a connected method for testing measurements, choosing the right composition law, retaining meaningful history, and finding the information an intervention actually needs. Each connection carries assumptions. Each biological application must earn its evidence.</p><a href="/discoveries/">Follow the ideas across the papers →</a></div></div>''')
home+='<section><div class="page-wrap"><p class="eyebrow">Choose a path through the conservatory</p><h2 class="section-title">Three doors. One enquiry.</h2><div class="route-grid">'+route('/discoveries/','The discoveries','What the programme contributes—and exactly what each result establishes.','specimens')+route('/predictions/','The open wagers','Predictions, competing explanations and the observations that could prove a model wrong.','entrance')+route('/biology/','The living project','A focused expedition into state, capacity, adaptation and recoverability.','biology')+'</div></div></section>'
home+=section('''<div class="split"><div><p class="eyebrow">A small instrument · A real distinction</p><h2 class="section-title">The same limits.<br>Different laws.</h2><p>Two effects can both lie between zero and one and still combine differently. Move the dial to compare two declared reference models.</p><p>The difference is useful: it tells us where an experiment may separate the models. Boundedness supplies the range; the mechanism supplies the rule.</p>'''+sources([7426978,6963978])+'''</div><div class="lab-demo" data-demo="composition"><span class="eyebrow">Combination lens / illustrative calculation</span><label for="effect">Matched individual effect <output id="effect-label">0.618</output></label><input id="effect" type="range" min="0.01" max="0.99" step="0.001" value="0.618"><div class="demo-values"><span>Bliss <strong id="bliss">0.854</strong></span><span>Loewe, n = 1 <strong id="loewe">0.764</strong></span><span>Gap <strong id="gap">0.090</strong></span></div><svg class="plot" viewBox="0 0 360 140" role="img" aria-label="Comparison of Bliss and common-slope-one Loewe effects"><path d="M0 115H360" stroke="#a2b790"/><rect id="bliss-bar" x="0" y="22" width="307" height="25" fill="#d8f57d"/><rect id="loewe-bar" x="0" y="69" width="275" height="25" fill="#e9bb70"/><text x="0" y="138" fill="#d4dfcb" font-size="12">0</text><text x="352" y="138" fill="#d4dfcb" font-size="12">1</text></svg><p class="fine soft">Bliss = 2e − e². Common-shape Loewe at Hill slope 1 = 2e/(1+e). The maximum raw gap occurs near 0.618; the most informative experiment also depends on noise. This is a model illustration, not drug advice.</p></div></div>''')
home+=section('''<div class="intro"><p class="section-tag">The next chapter</p><div><h2>Build biology deeply.</h2><p class="lead">One system with measured connections is more valuable than a thousand rooms without working experiments.</p><p>The next programme focuses on a living cell: what enters, what is stored, what is consumed, what senses the change, and what future remains possible. A result expands the map only when the connection survives a test.</p>'''+button('/biology/','See the biology expedition')+'</div></div>')
write('/','Life at the edge of possible',home)

themes=[
('composition','Arithmetic must be earned.','Conditional mathematics','Bounded values do not automatically add like distances on a ruler. An admitted composition law can supply a coordinate in which its operation becomes additive.','The programme organizes additive generators, five canonical projective flows, and the extra premises that select a geometric branch. The exact Bliss–Loewe gap offers a concrete model-discrimination example.','Classical Aczél theory is part of the foundation, not a new invention. The five-flow table requires its marked-triple restriction. Boundedness alone does not force artanh or one universal geometry.',[7426978,6963978,6800400,6754362,6773218,6767896,6756063],'PHARM-1'),
('state','A present must earn the name “state”.','Theorem and experimental method','Two histories can arrive at the same measured value and still produce different futures. If so, that value is missing predictive information.','State-law descent makes the failure precise. The proposed repair is measurable: preserve another distinction and demand improved prediction on untouched future challenges.','Exact quotient results are mathematical. Finite experiments need overlap, measurement-error control, predefined equivalence margins and a declared future panel.',[7425878,7426998,7347861,7304339],'BIO-1'),
('time','The order can be part of the cause.','Conditional mathematics; published motivation','An exposure total erases sequence. That is legitimate only when the relevant action laws permit the erasure.','Predictive Closure connects commuting actions to cumulative descriptions, and noncommuting actions to temporal grammar. The quadratic dose-response result identifies why gap experiments can reveal modes that additional challenge amplitudes cannot.','Reversal rejects a specified order-blind summary; it does not prove every scalar state model fails. The radiation examples draw on other researchers’ biological experiments.',[7427098,7426880,7427058,7302362],'RAD-2'),
('capacity','Capacity, response and reserve are different.','Biological models and testable hypotheses','A high antioxidant fraction is not a measurement of the available pool, regeneration rate or remaining rescue opportunity.','Finite pools, saturable repair, competing channels and slow control organize hormesis and distinct failure regimes. Response coefficients turn a heuristic amplitude factor into a quantity a same-system assay could measure.','The papers’ clinical forecasts remain conditional. The redox boundary model needs the documented equation repairs; reported recovery of known G6PD patterns is not a new clinical validation. Hormesis is conditional on the opposing-channel model.',[6754498,6754360,6761570,6858819,6858760,6858880],'REDOX-2'),
('hidden','A good fit can hide the decisive variable.','Identifiability results and simulations','An abundance histogram loses currents. Rare-allele data entangle selection and dominance. Cognitive covariance does not uniquely count causal handles.','Across ecology, genetics and cognition, the papers locate what a familiar observation cannot identify, then propose a different measurement: trajectories, the changing-frequency region, or intervention response.','These are distinct domain-specific results. Their shared logic is an observation problem; it is not evidence that the domains share one hidden physical force.',[6963360,6963958,6964098,6947578,7426882],'ECO-1'),
('evidence','A negative result can sharpen the map.','Reported secondary analyses','A constrained fit can work while its mechanism remains unidentified. An ordered archive can contain drift without violating fundamental physics.','The exoplanet analysis reports that current data do not select the atmospheric-loss coefficient. The quantum archive analysis separates heterogeneity and job-order structure. Prime computations distinguish exact representation identities from finite predictive performance.','These are manuscript-reported results, not rerun or independently replicated in this website rebuild. No new physical law or prime asymptotic theorem is established.',[6858878,6865159,6947578,7426882],'ARCHIVE-1'),
('action','Knowing enough means knowing enough to act.','Finite theorem; biological application prospective','Different physical states may allow the same acceptable action. Other apparently similar states require incompatible responses.','Action sufficiency defines the common-action test. Recoverability adds a further constraint: a useful distinction must be measured safely and soon enough to change the outcome.','Static action covers do not automatically make a sequential controller. The diagnostic selection-error bound is not, by itself, a biological failure probability.',[7427100,7427059,7181465,7426938],'ACT-2'),
('authority','An answer needs an evidence boundary.','Software architecture; finite checks','A fluent proposal, a supported statement and permission to act are different things.','Epistemic type safety makes stronger assertions require explicit witnesses. The evidence reviews similarly distinguish a drug intervention from the addition of legal force; evidence for one is not automatically evidence for the other.','The finite AI prototype is not a universal truth machine. The psychiatry papers contain a review and an explicit ethical argument; they do not derive treatment policy from boundedness.',[7426838,6779487,6907938,6858838],'AI-1')]
rows=''
for i,(slug,title,status,plain,achievement,limit,ids,pred) in enumerate(themes,1):
 rows+=f'<article class="theme-row anchor" id="{slug}"><span class="num">0{i}</span><div><span class="badge">{status}</span><h3>{title}</h3><p>{plain}</p>{sources(ids)}</div><div><p><strong>The contribution.</strong> {achievement}</p><p class="small"><strong>Where it stops.</strong> {limit}</p><a class="small" href="/predictions/?q={pred}">Open the next test →</a></div></article>'
dis=hero('The discoveries.<br><em>Their real shape.</em>','A synthesis by idea: what the work adds, what supports it, and where the next question begins.','specimens','The cabinet of contributions')
dis+=section('''<div class="prose"><h2>The sum is a method for finding what is missing.</h2><p class="lead">Begin with a bounded observable. Establish how it is measured and what operation it supports. Test whether its present retains enough history. Add a missing quantity only when an untouched future demonstrates its value.</p><p>The programme’s strongest collective contribution is this progression from constraints to tested representations and useful action. It brings mathematical structure and empirical failure conditions into the same research workflow. That is the architectural ambition; these pages do not claim priority over every related field or proof of a universal theory.</p></div><div class="diagram" aria-label="Connections between programme contributions"><a href="#composition">Bounds &amp; composition</a><a href="#state">Sufficient state</a><a href="#time">Temporal action</a><a href="#capacity">Biological capacity</a><a href="#action">Recoverable futures</a></div>'''+rows)
dis+=section('''<div class="split"><img src="/assets/biology.jpg" alt="Imagined biological conservatory" loading="lazy"><div><p class="eyebrow">The horizon, kept in view</p><h2 class="section-title">Awareness is a question.<br>IDA is a proposed instrument.</h2><p>The papers connect bounded belief, return dynamics, evidence capture and adaptive feedback to a possible study of awareness. Bayesian log-odds supplies one mathematical coordinate; it does not establish a neural mechanism or explain consciousness.</p><p>IDA’s immediate scientific task is smaller and testable: do independently measured return dynamics improve prediction, and can a matched feedback policy improve an independent outcome?</p>'''+button('/biology/#ida','Visit the IDA workstream')+sources([6987278,6774878,6858922])+'''</div></div>''')
write('/discoveries/','Eight connected contributions',dis)

def predrecord(f):
 ids=f['sources'];refs=''
 for sid in ids:
  p=byid.get(sid)
  if p:refs+=linkpaper(sid,f'{sid} · '+(', '.join('p'+str(n) for n in f.get('source_pages',{}).get(sid,[])[:6]) or 'source'))+' '
 detail=''.join(f'<dt>{name}</dt><dd>{e(f.get(key,""))}</dd>' for name,key in [('The test','next_test'),('What agreement would support','success_means'),('Failure or limitation','failure_means')])
 source='<details><summary>Read the original prediction</summary><blockquote class="quote">'+e(f['source_text'])+'</blockquote></details>' if f.get('source_text') else ''
 search=e(' '.join([f['id'],f['title'],f['domain'],f['status'],' '.join(ids),f.get('source_text',''),f.get('next_test','')]),quote=True)
 return f'<details class="record" id="{f["id"]}" data-search="{search}" data-domain="{e(f["domain"])}" data-kind="{e(f["record_kind"])}"><summary><div><span class="meta">{f["id"]} / {e(f["domain"])} / {e(f["record_kind"])}</span><h3>{e(f["title"])}</h3><span class="badge">{e(f["status"])}</span></div></summary><div class="record-body"><dl>{detail}</dl>{"<p class=note>"+e(f.get("caveat",f.get("use_notice","")))+"</p>" if f.get("caveat") or f.get("use_notice") else ""}{source}<p class="source-links">{refs}</p><a class="fine" href="#{f["id"]}">Permanent record link</a></div></details>'
allpred=A['families']+A['numbered_predictions']
domains=sorted({f['domain'] for f in allpred})
filters='<div class="filters"><input id="search" type="search" aria-label="Search predictions" placeholder="Search a prediction, idea or paper…"><select id="domain" aria-label="Filter by field"><option value="">Every field</option>'+''.join(f'<option>{e(x)}</option>' for x in domains)+'</select><select id="kind" aria-label="Filter by record type"><option value="">Both record types</option><option>Research family</option><option>Original numbered prediction</option></select></div>'
pred=hero('Good ideas<br><em>risk being wrong.</em>','Open the wagers. Inspect the assumptions. Find the observation that would change the answer.','entrance','The prediction field book')
pred+=section('<div class="chapter-aside"><div><h2 class="section-title">What would settle it?</h2><p>Explore <strong>41 research families</strong> and <strong>41 original numbered items</strong> extracted from five prediction lists. They overlap: they are not 82 independent discoveries. Mathematical gates, retrospective explanations, proposed experiments and open biological predictions keep their different status.</p></div><aside class="sticky-note"><h3>Trace every claim.</h3><p class="small">Each record leads to the source manuscript and its limits. All 41 papers also have a page-addressed index of prediction-bearing passages.</p><a href="/about/">Read the coverage statement →</a></aside></div>'+filters+'<p id="result-count" class="count" role="status" aria-live="polite">82 records</p><div data-filter-list>'+''.join(predrecord(f) for f in allpred)+'</div><p class="empty" id="empty" hidden>No records match. Try a broader term or clear the field filter.</p><p><a href="/data/atlas.json" download>Download the full public register and source index (JSON)</a></p>')
write('/predictions/','Predictions and failure criteria',pred)

bio=hero('The biology<br><em>conservatory.</em>','A living map, built one measured connection at a time. State, energy, control and the possibility of recovery.','biology','The next focused expedition')
bio+=section('''<div class="intro"><p class="section-tag">Our direction</p><div><h2>When does “recovered”<br>really mean recovered?</h2><p class="lead">Make this the first unifying biological question. A restored reading can conceal a depleted pool, a slow controller or a changed response to the next challenge.</p><p>The papers already supply the parts of a serious programme: finite-resource accounting, competing adaptive channels, history-conditioned state tests, a proposed rescue-window law and the distinction between prediction and action. The next achievement should connect those parts in one independently measured system.</p><p><strong>Recommended lead system:</strong> redox regulation in a tractable cultured-cell preparation, with a separately validated chemical assay. The immediate work is assay and data readiness. No animal or human experiment is launched by this website.</p></div></div>''')
bio+=section('''<p class="eyebrow">The shared biological map</p><h2 class="section-title">Follow what enters.<br>Measure what remains.</h2><div class="diagram"><a href="#energy">Supply &amp; pools</a><a href="#control">Sensing &amp; control</a><a href="#state">Retained state</a><a href="#recovery">Rechallenge &amp; fate</a></div><div class="table-scroll"><table class="comparison"><thead><tr><th>Workstream</th><th>Observable and action</th><th>Connection it must earn</th></tr></thead><tbody><tr id="energy"><td>Resources</td><td>Absolute pools, supply, consumption and regeneration; calibrated perturbation.</td><td>A reserve estimate predicts something a fraction alone misses.</td></tr><tr id="control"><td>Regulation</td><td>Signal fidelity, controller response time, capacity and surveillance readout.</td><td>A selective intervention distinguishes a slow controller from a depleted resource.</td></tr><tr id="state"><td>History and state</td><td>Different prior exposures, matched present and the same future challenge.</td><td>A retained distinction improves prediction in independent units and batches.</td></tr><tr id="recovery"><td>Recoverability</td><td>Specified rescue, withdrawal, rechallenge and independently measured durable fate.</td><td>Apparent recovery predicts continued function after support ends.</td></tr><tr><td>Energy and metabolism</td><td>Supply/demand and coupling efficiency under independently estimated losses.</td><td>The predicted binding-versus-slack interaction survives a controlled comparison.</td></tr><tr><td>Cells and communities</td><td>Lineages, growth, division, labelled trajectories and exchanges.</td><td>Individual-state rules transfer only through measured interactions and observation rules.</td></tr></tbody></table></div>'''+sources([7425878,7426938,6754360,6754498,6858880]))
bio+=section('''<div class="chapter-aside"><div><p class="eyebrow">First campaign / proposed protocol</p><h2 class="section-title">The recovered-present test.</h2><div class="steps"><article class="step"><h3>Declare the measurement</h3><p>Fix preparation, units, time horizon, future panel and a functionally meaningful equivalence margin. Verify the assay and matching error.</p></article><article class="step"><h3>Create different pasts</h3><p>Use controlled histories that overlap at the chosen present measurement. Preserve same-history controls and all intervention records.</p></article><article class="step"><h3>Challenge the present</h3><p>Apply the identical future. Compare a frozen snapshot baseline, a conventional mechanistic model, and the predeclared resource/history extension.</p></article><article class="step"><h3>Test the repair</h3><p>Freeze the added representation. Evaluate new histories and independent batches. Demand both better prediction and a controlled residual-history test.</p></article></div><h3>What counts as success?</h3><p>The initial measurement shows a resolved, functionally relevant common-future difference beyond matching error. An independently measurable added quantity improves a predefined held-out prediction score over strong baselines, and its residual-history discrepancy is inside the predefined equivalence margin.</p><h3>What counts as failure?</h3><p>Adequate equivalence supports the simpler representation in the tested scope. No gain rejects the proposed addition. Poor overlap, noisy assays or a confidence interval crossing the decision boundary give <strong>unresolved</strong>, not success.</p><h3>Before substantial experimental work</h3><p>Choose the biological endpoint and pilot-estimated precision, establish data access, then freeze effect margins, sample-size justification, split rules and stopping criteria. The website does not invent numerical success thresholds before those measurements exist.</p></div><aside class="sticky-note"><h3>Keep the baseline strong.</h3><p class="small">The extension must beat a well-specified conventional model at comparable data and measurement cost. It must not merely beat a deliberately weak snapshot predictor.</p><p class="small">A positive result identifies useful missing predictive information. A physical memory carrier needs a further selective intervention.</p><a href="/predictions/?q=BIO-1">Open the paper commitments →</a></aside></div>''')
bio+=section('''<div class="split"><div><p class="eyebrow">A bounded-resource lens</p><h2 class="section-title">A fraction cannot<br>tell you the reserve.</h2><p>Hold the reduced fraction fixed while changing the total glutathione pool. The available accounting budget changes even though the fraction is identical.</p><p class="small">In the declared fixed-volume GPx/GR ledger, GSH/2 + NADPH is a necessary resource budget for peroxide-equivalent processing. It assumes nonnegative pools and the specified stoichiometry; it does not establish a reaction rate, reachable endpoint or survival.</p></div><div class="lab-demo" data-demo="reserve"><p class="eyebrow">Synthetic resource ledger / mM</p><label for="pool">Total glutathione equivalents <output id="pool-label">2.00</output> mM</label><input id="pool" type="range" min="0.2" max="4" value="2" step="0.05"><label for="fraction">Reduced fraction <output id="fraction-label">0.90</output></label><input id="fraction" type="range" min="0.1" max="0.99" value="0.9" step="0.01"><label for="nadph">NADPH <output id="nadph-label">0.20</output> mM</label><input id="nadph" type="range" min="0" max="1" value="0.2" step="0.01"><div class="demo-values"><span>GSH <strong id="gsh">1.80</strong></span><span>Necessary budget <strong id="budget">1.10</strong></span></div><p class="fine soft">GSH = total glutathione equivalents × reduced fraction. Budget = GSH/2 + NADPH. No external supply, no rate or viability prediction. This is an explanatory model, not a biological measurement.</p></div></div>''')
bio+=section('''<p class="eyebrow">What the Observatory already taught us</p><h2 class="section-title">A useful signal.<br>And an important rejection.</h2><div class="table-scroll"><table class="comparison"><thead><tr><th>Case</th><th>Result already recorded</th><th>Meaning for the new programme</th></tr></thead><tbody><tr><td>Chlamydomonas model</td><td>Equal total light over 48 hours produced one cell versus eight descendants under different schedules, with nearly equal total lineage volume.</td><td>A synthetic example of timing and readout separation in a published model. It does not establish a new algal mechanism.</td></tr><tr><td>Numerical stress test</td><td>An apparent hidden-state lag vanished under a more accurate solver.</td><td>Numerical convergence is part of the evidence boundary.</td></tr><tr><td>Held-out cell prediction</td><td>Adding growth-history data worsened overall Brier score by 3.30% on the recorded 3,679 predictions.</td><td>More history is not automatically useful. The proposed extra state must earn its place.</td></tr></tbody></table></div><p><a href="https://github.com/thantiklermcirony/empirical-observatory/tree/main/research">Read the preserved experiment record ↗</a></p>''')
bio+=section('''<div id="ida" class="split anchor"><img src="/assets/specimens.jpg" alt="Imaginative glass specimen cabinet" loading="lazy"><div><p class="eyebrow">IDA / A distinct research workstream</p><h2 class="section-title">How does a system<br>find its way back?</h2><p>IDA asks whether the path of return after perturbation contains information that an instantaneous reading misses. Its first gate is a real-signal prediction test against static and conventional time-series baselines, with person and session holdouts.</p><p>Only after that gate should feedback be tested against matched replay, sham and conventional control. Gamma-to-belief and inter-brain sinh coupling are separate hypotheses. None of these results would, by itself, explain consciousness.</p>'''+sources([6987278,6774878,6858922])+'''<p><a href="/predictions/?q=IDA">Read IDA’s tests →</a></p></div></div>''')
write('/biology/','The biology conservatory',bio)

paperrows=''
for p in sorted(P,key=lambda x:(x['role'],x['title'])):
 search=e(' '.join([p['title'],p['role'],p['ssrn_id'],p['contribution']]),quote=True)
 paperrows+=f'<article class="record" data-search="{search}"><span class="meta">{e(p["kind"])} · {p["ssrn_id"]} · {p["page_count"]} PDF pages</span><h3>{linkpaper(p["ssrn_id"])}</h3><p class="small">{e(p["contribution"])}</p><span class="badge">{e(p["evidence"])}</span></article>'
library=hero('The field<br><em>library.</em>','All 41 manuscript records, organized by their role in the programme. Open a source to inspect its contribution, original text and current limits.','specimens','Every idea has a source')
library+=section('<div class="prose"><h2>A connected collection.</h2><p>The inventory contains 11 current records and 30 predecessor or related records. Some repeat or revise earlier results; one PDF contains a substantial bundled collection. The count is not a count of independent discoveries.</p></div><div class="filters"><input id="search" type="search" aria-label="Search manuscripts" placeholder="Find an idea, title or SSRN number…"></div><p id="result-count" class="count" aria-live="polite">41 manuscripts</p><div data-filter-list>'+paperrows+'</div><p id="empty" class="empty" hidden>No manuscripts match this search.</p>')
write('/papers/','The manuscript library',library)
for p in P:
 relevant=[f for f in allpred if p['ssrn_id'] in f['sources']]
 predlinks=''.join(f'<li><a href="/predictions/?q={f["id"]}#{f["id"]}">{e(f["id"]+" · "+f["title"])}</a></li>' for f in relevant)
 body=hero(e(p['role']),e(p['contribution']),'specimens',p['kind']+' manuscript · '+p['ssrn_id'])
 body+=section(f'<a class="return-link" href="/papers/">← Back to the library</a><div class="chapter-aside"><article class="prose"><h2>{e(p["title"])}</h2><span class="badge">{e(p["evidence"])}</span><p class="note"><strong>Current scope.</strong> {e(p["scope"])}</p><h3>What it adds to the whole</h3><p>{e(p["contribution"])}</p><h3>Predictions and research connections</h3>'+('<ul>'+predlinks+'</ul>' if relevant else '<p>This record primarily contributes a conditional mathematical result or a synthesis. No separate empirical prediction family is assigned here; inspect its source passages below for conditions and proposed extensions.</p>')+f'<h3>The abstract</h3><p class="small">Supplied manuscript · PDF page(s) {", ".join(map(str,p["abstract_pages"]))}. Original wording; read alongside the scope note.</p><blockquote class="quote">{e(p["abstract"])}</blockquote><h3>Conclusion or closing discussion</h3><p class="small">Page addresses are retained in the excerpt. These are author claims, not an independent validation certificate.</p><details class="record"><summary>Open the closing section</summary><blockquote class="quote">{e(p["closing"])}</blockquote></details><h3>Prediction-bearing source passages</h3><p class="small">A full-text retrieval aid, including hypotheses, falsifiers, comparisons and mentions of predictions. A matching passage is not automatically a distinct prediction.</p>'+''.join(f'<details class="record"><summary>PDF page {x["page"]}</summary><blockquote class="quote">{e(x["text"])}</blockquote></details>' for x in p['prediction_passages'])+f'</article><aside class="sticky-note"><h3>Source receipt</h3><p class="small">{p["page_count"]} PDF pages · {e(p["kind"])} record</p><p class="small">Abstract and closing discussion reviewed. Original numbered lists checked where present.</p><p><a href="{p["url"]}">Open the SSRN record ↗</a></p><p class="fine">The online record may contain a different revision. Parity has not been certified.</p><details><summary class="small">Local source SHA-256</summary><p class="fine" style="overflow-wrap:anywhere">{p["sha256"]}</p></details><p class="fine">A hash identifies bytes. It does not verify a proof or establish novelty.</p><a href="/about/">Coverage and method →</a></aside></div>')
 write('/papers/'+p['key']+'/',p['title'],body,p['contribution'])

about=hero('A map you<br><em>can inspect.</em>','The sources, the limits and the work required to turn a promising idea into established knowledge.','entrance','Evidence and coverage')
about+=section('''<div class="prose"><h2>What has been checked?</h2><p>On 13 September 2026, the supplied 41-record manuscript collection was re-extracted and its text matched the existing reading corpus for all 41 records. Abstracts and conclusions or closing discussions were read, with missing continuation pages recovered. The PDFs contain 1,098 pages in total; this is extraction coverage, not a claim that every proof on every page has been independently verified.</p><p>The presentation groups the work into eight contributions. The register retains 41 previously consolidated research families and adds the 41 original numbered items from the five explicitly enumerated lists inspected here: hormesis (5), metabolic-control attenuation (6), the four-role architecture (17), aluminium pharmacology (6), and ecological currents (7).</p><p>Those counts overlap. Some statements are retrospective reclassifications; some are conditional mathematical consequences; some are prospective hypotheses. A separate index retains relevant passages on 471 main-text pages across the entire collection.</p><h3>What does “complete” mean here?</h3><p>Complete against this declared 41-record inventory and those five numbered lists. Keyword retrieval cannot certify that every implicit prediction, every equivalent formulation or every mathematical corollary has been found. The coverage record makes that limit visible, and the original passages make further corrections possible.</p><h3>Evidence labels</h3><ul><li><strong>Conditional mathematics:</strong> a result stated under explicit premises. Website inclusion is not independent proof verification.</li><li><strong>Simulation:</strong> a result inside a specified computational model. Solver accuracy and implementation checks matter.</li><li><strong>Secondary analysis:</strong> a reported analysis of existing data, with its original sampling and measurement limits.</li><li><strong>Hypothesis or prospective test:</strong> an empirical commitment awaiting an adequate test.</li><li><strong>Review or synthesis:</strong> an organization or interpretation of existing results, with any normative premise retained.</li></ul><h3>Corrections belong in the achievement record.</h3><p>The later work restricts earlier universal-coordinate claims, separates current from abundance, distinguishes transient recovery from durable fate, and preserves failed predictive additions. The historical aluminium “elliptic signature” is retained with an explicit warning: its stated geometric rationale is unsupported. These corrections are part of the programme’s development.</p><h3>What is not certified?</h3><p>Global priority, independent proof checking, clinical efficacy, universal physical coverage and online-version parity. An archive hash certifies source identity only. No number of manuscript records substitutes for these separate tasks.</p><h3>Publication and privacy</h3><p>This is the new public presentation of the boundedness programme. The Observatory’s previous code and experiment history are preserved in their existing repositories. Only the supplied manuscript content and already public programme results are included. The site itself is informational: its two dials execute declared local formulas and do not call hosted AI or collect enquiry records.</p><p>Third-party fonts are loaded from Google Fonts; the artwork is AI-generated illustration. No analytics or advertising scripts are added.</p><h3>Reproduce or correct the map</h3><p>Download the public content and source receipts, or inspect the repository. The static site is generated from that content. A correction should identify the paper, version, page and affected claim, with a reason and supporting evidence.</p><p><a href="/data/atlas.json" download>Download the public source ledger</a> · <a href="'''+REPO+'''">Inspect the repository</a></p></div>''')
write('/about/','Evidence and source coverage',about)
(D/'data').mkdir(exist_ok=True);shutil.copyfile(R/'content/atlas.json',D/'data/atlas.json')
(D/'404.html').write_text((D/'index.html').read_text(encoding='utf-8').replace('<h1>Life at<br>the edge of<br><em>possible.</em></h1>','<h1>A path<br>not yet<br><em>mapped.</em></h1>'),encoding='utf-8')
(R/'README.md').write_text('''# The Boundedness Atlas

[![Enter the Boundedness Atlas](dist/assets/entrance.jpg)]('''+BASE+''')

## [Enter the Atlas →]('''+BASE+''')

Daniel John Murray’s research programme, presented by connected ideas: bounded composition, predictive state, temporal action, biological capacity, useful intervention and evidence.

- **41 manuscript records**, with abstracts and closing sections reviewed.
- **8 connected contributions**, each with a statement of evidence and scope.
- **41 research families + 41 original numbered items**, overlapping rather than independent discoveries.
- A source index across **471 prediction-bearing main-text pages**, with manuscript hashes and page addresses.
- A focused **biology conservatory**, beginning with the difference between apparent recovery and recoverable capacity.

The site distinguishes conditional mathematics, simulations, secondary analyses and prospective hypotheses. It does not certify global novelty, independent proof verification or universal predictive accuracy. Historical claims and corrections remain visible.

## Rebuild

Python 3, standard library only:

```sh
python build_site.py
python -m http.server 4173 --directory dist
```

Reviewed content lives in `content/atlas.json`; authored assets live in `dist/assets`, `dist/style.css` and `dist/app.js`. `build_site.py` regenerates pages and the public data download. No API keys or hosted AI calls are required. Source receipts refer to the supplied local manuscript revisions; online SSRN parity is not certified.

The previous [Empirical Observatory](https://github.com/thantiklermcirony/empirical-observatory) and [programme architecture](https://github.com/thantiklermcirony/empirical-architecture) remain preserved. Private research has not been included.

Artwork: three original AI-generated botanical illustrations. Exact prompts are recorded in `IMAGE_PROMPTS.json`. They are creative illustrations, not scientific data.

No new blanket license is applied to the author’s manuscripts or pre-existing work. Consult their individual source terms; the Atlas grants no rights over cited third-party material.
''',encoding='utf-8')
(R/'PUBLICATION_MANIFEST.json').write_text(json.dumps({'date':'2026-09-13','coverage':A['coverage'],'files':{str(p.relative_to(R)).replace('\\','/'):hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted(D.rglob('*')) if p.is_file()}},indent=2),encoding='utf-8')
print('Generated',len(list(D.rglob('index.html'))),'pages;',len(allpred),'overlapping prediction records.')
